mapper.select:
SELECT b.name AS branchName, m.name AS materialName, m.spec AS spec, s.quantity AS quantity, m.safe_stock AS safeStock, CASE WHEN s.quantity <= m.safe_stock THEN '预警' ELSE '正常' END AS warning FROM t_stock s JOIN t_material m ON s.material_id = m.id AND m.deleted = 0 JOIN t_branch b ON s.branch_id = b.id AND b.deleted = 0
AND s.branch_id = #{branchId}
ORDER BY b.id, m.id
